package com.stageclick.metronome;

import android.app.*;
import android.os.*;
import android.media.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;

public class MainActivity extends Activity {
 final int BG=0xff10171d, CARD=0xff1b262e, TEXT=0xffeef5f5, MUTE=0xff91a4ad, ACCENT=0xffa9ed77;
 final String[] METERS={"4/4","3/4","2/4","5/4","7/4","6/8","9/8","12/8"};
 ArrayList<Song> songs=new ArrayList<>(); int selected=0; volatile int bpm=120, beats=4, division=1, subdivision=1, sound=0; volatile boolean running=false; volatile long revision=0; volatile boolean accent=true; AudioTrack track; Thread audioThread; Handler handler=new Handler();
 LinearLayout root,dots,list; TextView tempo,title,detail,nextLabel; Button play, splitButton; Spinner meter; SeekBar slider; boolean updating=false; long lastTap=0; ArrayList<Long> taps=new ArrayList<>();
 static class Song { String name,meter; int bpm, split; Song(String n,int b,String m){this(n,b,m,1);} Song(String n,int b,String m,int x){name=n;bpm=b;meter=m;split=x==2?2:1;} }
 public void onCreate(Bundle b){super.onCreate(b); getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON); load(); build(); applySong(0);}
 int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 GradientDrawable shape(int color,int radius){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(dp(radius));return g;}
 TextView text(String s,int size,int color){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(color);v.setPadding(0,dp(3),0,dp(3));return v;}
 Button button(String s,Runnable action){Button v=new Button(this);v.setText(s);v.setTextColor(TEXT);v.setAllCaps(false);v.setBackground(shape(CARD,14));v.setOnClickListener(w->action.run());return v;}
 void add(LinearLayout parent,View v,int h){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,h<0?h:dp(h));p.setMargins(0,dp(5),0,dp(5));parent.addView(v,p);}
 LinearLayout row(){LinearLayout v=new LinearLayout(this);v.setGravity(Gravity.CENTER_VERTICAL);return v;}
 void cell(LinearLayout r,View v){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(52),1);p.setMargins(dp(3),0,dp(3),0);r.addView(v,p);}
 void build(){ScrollView scroll=new ScrollView(this);scroll.setBackgroundColor(BG);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(22),dp(12),dp(22),dp(28));scroll.addView(root);setContentView(scroll);scroll.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});
 add(root,text("STAGE CLICK    /    LIVE METRONOME",12,ACCENT),-2);
 title=text("",26,TEXT);title.setTypeface(null,Typeface.BOLD);add(root,title,-2);detail=text("",13,MUTE);add(root,detail,-2);
 tempo=text("120",86,TEXT);tempo.setGravity(Gravity.CENTER);tempo.setTypeface(Typeface.create("sans-serif-light",0));add(root,tempo,90);
 TextView unit=text("BPM",13,ACCENT);unit.setGravity(Gravity.CENTER);add(root,unit,-2);
 dots=row();dots.setGravity(Gravity.CENTER);add(root,dots,42);
 slider=new SeekBar(this);slider.setMax(280);slider.setProgress(90);slider.setProgressTintList(android.content.res.ColorStateList.valueOf(ACCENT));slider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int p,boolean user){if(user)setTempo(p+20);}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});add(root,slider,40);
 LinearLayout controls=row();cell(controls,button("−",()->setTempo(bpm-1)));cell(controls,button("TAP",()->tap()));cell(controls,button("+",()->setTempo(bpm+1)));add(root,controls,52);
 meter=new Spinner(this);ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,METERS);meter.setAdapter(adapter);meter.setBackgroundTintList(android.content.res.ColorStateList.valueOf(ACCENT));meter.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int pos,long id){if(!updating){setMeter(METERS[pos]);}}public void onNothingSelected(AdapterView<?> p){}});add(root,meter,48);
 LinearLayout options=row();Button ac=button("강박 ON",()->{});ac.setOnClickListener(v->{accent=!accent;ac.setText(accent?"강박 ON":"강박 OFF");revision++;});cell(options,ac);Button voice=button("소리: 우드",()->{});voice.setOnClickListener(v->{sound=(sound+1)%3;voice.setText(new String[]{"소리: 우드","소리: 비프","소리: 클릭"}[sound]);});cell(options,voice);add(root,options,52);splitButton=button("",()->{subdivision=subdivision==1?2:1;updateSplit();revision++;});add(root,splitButton,48);
 play=button("▶  시작",()->{if(running)stop();else start();});play.setBackground(shape(ACCENT,16));play.setTextColor(BG);add(root,play,62);
 Button next=button("다음 곡  →",()->applySong((selected+1)%songs.size()));next.setTextSize(21);add(root,next,66);nextLabel=text("",13,MUTE);add(root,nextLabel,-2);
 add(root,text("SETLIST  /  곡 프리셋",18,TEXT),-2);add(root,text("곡을 눌러 선택 · 길게 눌러 편집 / 삭제",12,MUTE),-2);
 list=new LinearLayout(this);list.setOrientation(1);add(root,list,-2);
 LinearLayout save=row();cell(save,button("+ 새 곡",()->edit(-1)));cell(save,button("현재 설정 저장",()->{Song s=songs.get(selected);s.bpm=bpm;s.meter=METERS[meter.getSelectedItemPosition()];s.split=subdivision;save();refresh();}));add(root,save,52);
 add(root,text("화면을 켠 상태로 사용하세요. 통화나 다른 앱으로 이동하면 재생이 멈춥니다.",12,MUTE),-2);
 }
 void setTempo(int n){bpm=Math.max(20,Math.min(300,n));tempo.setText(""+bpm);slider.setProgress(bpm-20);revision++;}
 void setMeter(String m){String[] parts=m.split("/");beats=Integer.parseInt(parts[0]);division=m.endsWith("/8")?3:1;detail.setText(m+"  ·  "+(division==3?"점4분음표 = BPM · 8분음표 클릭":"4분음표 = BPM"));updateSplit();revision++;drawDots(-1);}
 void updateSplit(){if(splitButton!=null)splitButton.setText(subdivision==2?"한 박당 클릭: 2번 (분할)":division==3?"한 박당 클릭: 3번 (기본)":"한 박당 클릭: 1번 (기본)");}
 void drawDots(int active){dots.removeAllViews();for(int i=0;i<beats;i++){TextView d=text(""+(i+1),14,i==active?BG:MUTE);d.setGravity(Gravity.CENTER);d.setPadding(0,0,0,0);d.setBackground(shape(i==active?ACCENT:CARD,20));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(dp(beats>9?22:28),dp(28));p.setMargins(dp(2),0,dp(2),0);dots.addView(d,p);}}
 void applySong(int index){selected=index;Song s=songs.get(index);subdivision=s.split;setTempo(s.bpm);updating=true;meter.setSelection(Arrays.asList(METERS).indexOf(s.meter));updating=false;setMeter(s.meter);refresh();}
 void refresh(){title.setText(songs.get(selected).name);Song n=songs.get((selected+1)%songs.size());nextLabel.setText("NEXT  "+n.name+"  ·  "+n.bpm+" BPM  ·  "+n.meter+(n.split==2?" · 2분할":""));list.removeAllViews();for(int i=0;i<songs.size();i++){final int index=i;Song s=songs.get(i);Button b=button((i==selected?"●  ":(i+1)+"  ")+s.name+"     "+s.bpm+" · "+s.meter+(s.split==2?" · 2분할":""),()->applySong(index));b.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);b.setPadding(dp(16),0,dp(8),0);if(i==selected)b.setTextColor(ACCENT);b.setOnLongClickListener(v->{new AlertDialog.Builder(this).setTitle(s.name).setItems(new String[]{"편집","위로 이동","아래로 이동","삭제"},(d,which)->{if(which==0)edit(index);else if(which==3){if(songs.size()==1)return;Song current=songs.get(selected);songs.remove(index);selected=Math.max(0,songs.indexOf(current));applySong(selected);save();}else{int to=index+(which==1?-1:1);if(to>=0&&to<songs.size()){Song current=songs.get(selected);Collections.swap(songs,index,to);selected=songs.indexOf(current);save();refresh();}}}).show();return true;});add(list,b,54);}}
 void edit(int index){LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(22),dp(8),dp(22),0);EditText name=new EditText(this);name.setHint("곡 이름");EditText speed=new EditText(this);speed.setHint("BPM (20–300)");speed.setInputType(2);Spinner sig=new Spinner(this);sig.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,METERS));Song s=index<0?new Song("",bpm,METERS[meter.getSelectedItemPosition()],subdivision):songs.get(index);name.setText(s.name);speed.setText(""+s.bpm);sig.setSelection(Arrays.asList(METERS).indexOf(s.meter));box.addView(name);box.addView(speed);box.addView(sig);Spinner splitChoice=new Spinner(this);splitChoice.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"기본 클릭 (복합박자는 3번)","한 박당 클릭 2번"}));splitChoice.setSelection(s.split==2?1:0);box.addView(splitChoice);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(index<0?"새 곡 프리셋":"프리셋 편집").setView(box).setNegativeButton("취소",null).setPositiveButton("저장",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{int n;try{n=Integer.parseInt(speed.getText().toString());}catch(Exception e){n=0;}if(n<20||n>300){speed.setError("20~300 BPM을 입력하세요");return;}String nm=name.getText().toString().trim();if(nm.isEmpty()){name.setError("곡 이름을 입력하세요");return;}Song result=new Song(nm,n,METERS[sig.getSelectedItemPosition()],splitChoice.getSelectedItemPosition()==1?2:1);if(index<0)songs.add(result);else songs.set(index,result);save();if(index==selected)applySong(selected);else refresh();dialog.dismiss();}));dialog.show();}
 void tap(){long now=SystemClock.elapsedRealtime();if(now-lastTap>2000)taps.clear();lastTap=now;taps.add(now);if(taps.size()>6)taps.remove(0);if(taps.size()>1)setTempo((int)Math.round(60000.0*(taps.size()-1)/(now-taps.get(0))));}
 void load(){try{JSONArray a=new JSONArray(getPreferences(0).getString("songs","[]"));for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);String m=o.getString("meter");if(Arrays.asList(METERS).contains(m))songs.add(new Song(o.getString("name"),Math.max(20,Math.min(300,o.getInt("bpm"))),m,o.optInt("split",1)));}}catch(Exception ignored){}if(songs.isEmpty()){songs.add(new Song("첫 번째 곡",120,"4/4"));songs.add(new Song("두 번째 곡",90,"3/4"));songs.add(new Song("세 번째 곡",72,"6/8"));}}
 void save(){JSONArray a=new JSONArray();for(Song s:songs){JSONObject o=new JSONObject();try{o.put("name",s.name);o.put("bpm",s.bpm);o.put("meter",s.meter);o.put("split",s.split);a.put(o);}catch(Exception ignored){}}getPreferences(0).edit().putString("songs",a.toString()).apply();}
 void start(){running=true;play.setText("■  정지");audioThread=new Thread(()->audioLoop(),"StageClickAudio");audioThread.start();}
 void audioLoop(){final Thread owner=Thread.currentThread();android.os.Process.setThreadPriority(android.os.Process.THREAD_PRIORITY_AUDIO);int sr=48000;AudioTrack local=null;try{local=new AudioTrack.Builder().setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build()).setAudioFormat(new AudioFormat.Builder().setSampleRate(sr).setEncoding(AudioFormat.ENCODING_PCM_16BIT).setChannelMask(AudioFormat.CHANNEL_OUT_MONO).build()).setBufferSizeInBytes(Math.max(2048,AudioTrack.getMinBufferSize(sr,4,2))).setTransferMode(AudioTrack.MODE_STREAM).build();track=local;local.play();short[] block=new short[240];double until=0;int beat=0,click=99999;boolean strong=false,offbeat=false;long seen=-1;while(running){long rev=revision;if(seen!=rev){seen=rev;until=0;beat=0;}for(int j=0;j<block.length;j++){if(until<=0){int rate=subdivision==2?2:division;int current=beat*division/rate;offbeat=beat%rate!=0;strong=accent&&(beat==0||(division==3&&!offbeat));click=0;beat=(beat+1)%(beats/division*rate);until+=sr*60.0/bpm/rate;long stamp=seen;handler.postDelayed(()->{if(running&&revision==stamp)drawDots(current);},25);}double t=click/(double)sr;double freq=strong?1700:offbeat?850:1100;double wave=sound==2?(click<35?1:0):Math.sin(2*Math.PI*freq*t);double decay=Math.exp(-t*(sound==0?210:110));block[j]=(short)(wave*decay*(strong?23000:offbeat?9000:14000));click++;until--;}local.write(block,0,block.length);}}catch(Exception e){handler.post(()->Toast.makeText(this,"오디오를 시작할 수 없습니다",Toast.LENGTH_LONG).show());}finally{if(local!=null){local.release();}track=null;handler.post(()->{if(audioThread!=owner)return;running=false;play.setText("▶  시작");drawDots(-1);});}}
 void stop(){running=false;if(audioThread!=null){try{audioThread.join(500);}catch(InterruptedException ignored){}}play.setText("▶  시작");drawDots(-1);}
 protected void onPause(){super.onPause();stop();}
}
